package dev.zomboid.mts;
import java.util.*;
public final class Mechanics {
 public static final Set<String> CARS=Set.of("scout","merc230","fordmustang69","gmcbrig","firetruck","quad");
 public static final Set<String> BELROFT=Set.of("adventure","adventure_ambulance","adventure_police","brotchen","bullfrog","citadel","conquest","conquest_police","emperor","emperor_fire_chief","emperor_police","harpy","horizon","keeper","keeper_fire_chief","keeper_police","nugget","nugget_police","paragon","silver");
 static String p="minecrafttransportsimulator.";
 public static boolean car(Object vehicle){if(vehicle==null)return false;Object d=R.get(vehicle,"definition");return "mtsofficialpack".equals(R.get(d,"packID"))&&CARS.contains(R.get(d,"systemName"))||"belroftmotors".equals(R.get(d,"packID"))&&BELROFT.contains(R.get(d,"systemName"));}
 static Object vehicle(Object e){return R.type(p+"entities.instances.EntityVehicleF_Physics").isInstance(e)?e:R.type(p+"entities.instances.APart").isInstance(e)?R.get(e,"vehicleOn"):null;}
 static double value(Object e,String field){return R.num(R.get(R.get(e,field),"currentValue"));}
 public static double fraction(double damage,double max){return max<=0?1:Math.max(0,Math.min(1,1-damage/max));}
 static double health(Object e){return fraction(value(e,"damageVar"),R.num(R.get(R.get(R.get(e,"definition"),"general"),"health")));}
 static Object packItem(String id){String[] bits=id.split(":",2);return R.call(R.type(p+"packloading.PackParser"),"getItem",bits[0],bits[1]);}
 public static void ensure(Object e){if(!car(e))return;List<?> defs=(List<?>)R.get(R.get(e,"definition"),"parts");List<?> parts=(List<?>)R.get(e,"partsInSlots");if(!R.yes(R.call(R.get(e,"world"),"isClient")))for(int i=0;i<defs.size();i++){Object d=defs.get(i);if(!"mtsofficialpack:zomboid_trunk".equals(R.get(d,"defaultPart"))||parts.get(i)!=null)continue;Object item=packItem("mtsofficialpack:zomboid_trunk");if(item==null)throw new IllegalStateException("Missing functional trunk definition");R.call(e,"addPartFromStack",R.call(item,"getNewStack",(Object)null),null,i,true,false);}instruments(e);}
 static void instruments(Object e){List<Object> items=(List<Object>)R.get(e,"instruments");List<?> defs=(List<?>)R.get(R.get(e,"definition"),"instruments");if(defs==null)return;for(int i=0;i<defs.size();i++){Object d=defs.get(i);if(R.num(R.get(d,"scale"))>.00001)continue;Object id=R.get(d,"defaultInstrument");if(id==null)continue;while(items.size()<=i)items.add(null);if(items.get(i)==null){Object item=packItem(id.toString());if(item!=null)items.set(i,item);}}}
 public static boolean scanner(Object item){return "SCANNER".equals(R.get(R.get(R.get(item,"definition"),"item"),"type").toString());}
 public static boolean scan(Object item,Object e,Object player,boolean right){if(FamilyWorkshop.blockRepair(item,e,player,right))return true;if(!right||!scanner(item))return false;Object v=vehicle(e);if(v==null)return false;if(!R.yes(R.call(R.get(v,"world"),"isClient"))&&!R.yes(R.get(R.get(v,"lockedVar"),"isActive"))){Inspection.start(v,player);}return true;}
 static double distance(Object a,Object b){double sum=0;for(String k:List.of("x","y","z")){double n=R.num(R.get(a,k))-R.num(R.get(b,k));sum+=n*n;}return sum;}
 public static Object target(Object item,Object e,Object hit){Object d=R.get(item,"definition");if(!"REPAIR_PACK".equals(R.get(R.get(d,"item"),"type").toString()))return e;Object repair=R.get(d,"repair");List<?> types=(List<?>)R.get(repair,"repairableParts");if(types==null||types.stream().noneMatch(s->s.toString().startsWith("engine"))||R.type(p+"entities.instances.PartEngine").isInstance(e))return e;Object v=vehicle(e);if(v==null)return e;Object center=R.get(hit,"globalCenter");return ((Collection<Object>)R.get(v,"engines")).stream().filter(engine->{String type=R.get(R.get(R.get(engine,"definition"),"generic"),"type").toString();return types.stream().anyMatch(prefix->type.startsWith(prefix.toString()));}).min(Comparator.comparingDouble(engine->distance(R.get(engine,"position"),center))).orElse(e);}
 public static void open(Object v,Object player){Object item=R.call(R.call(player,"getHeldStack"),"getItem");if(RoadDriving.transport(v)||item!=null&&R.type(p+"items.instances.ItemItem").isInstance(item)&&scanner(item))R.make("dev.zomboid.mts.CheckGUI",v);else R.make(p+"guis.instances.GUIInstruments",v);}
 static Object label(Object gui,int x,int y,String text,float size,Object color){Object l=R.make(p+"guis.components.GUIComponentLabel",x,y,color,text,R.get(R.type(p+"rendering.RenderText$TextAlignment"),"LEFT_ALIGNED"),size);R.set(l,"ignoreGUILightingState",true);R.call(gui,"addComponent",l);return l;}
 static final Map<Object,List<Object>> checkIndicators=new WeakHashMap<>();
 public static int severity(double condition){return condition>.66?0:condition>.33?20:40;}
 public static void checkSetup(Object gui){Workshop.setup(gui);}
 public static List<String> report(Object v){List<String> lines=new ArrayList<>();lines.add(String.format("Carroceria: %.0f%%     Combustible: %.0f%%",health(v)*100,fuel(v)*100));lines.add(String.format("Bateria: %.0f%%",battery(v)*100));int i=0;for(Object engine:(Collection<?>)R.get(v,"engines")){lines.add(String.format("Motor %d: %s    Estado %.0f%%",++i,R.yes(R.get(engine,"running"))?"encendido":"apagado",health(engine)*100));lines.add("Caja: "+(R.yes(R.get(R.get(engine,"isAutomaticVar"),"isActive"))?"automatica":"manual")+"  Marcha: "+gear(engine));lines.add(String.format("RPM %.0f    Temperatura %.0f C",R.num(R.get(engine,"rpm")),R.num(R.get(engine,"temp"))));lines.add(String.format("Aceite %.1f    Desgaste %.1f h",R.num(R.get(engine,"pressure")),value(engine,"hoursVar")));if(health(engine)<1||value(engine,"hoursVar")>0)lines.add("Necesita mantenimiento: kit de motor + clic derecho.");else lines.add("Motor en buen estado.");}if(i==0)lines.add("No hay motor instalado.");lines.add("Reparar con el motor apagado y el coche detenido.");lines.add("Kit de carroceria: clic derecho en el coche.");lines.add("ESC para cerrar.");return lines;}
 public static void checkState(Object gui){Workshop.state(gui);}
 static double fuel(Object v){return Math.max(0,Math.min(1,R.num(R.call(R.get(v,"fuelTank"),"getFluidLevel"))/Math.max(1,R.num(R.get(R.get(R.get(v,"definition"),"motorized"),"fuelCapacity")))));}
 static double battery(Object v){return Math.max(0,Math.min(1,R.num(R.get(v,"electricPower"))/Math.max(.001,value(v,"batteryCapacityVar"))));}
 static String gear(Object e){int n=(int)value(e,"currentGearVar");return n<0?"R":n==0?"N":Integer.toString(n);}
 public static void gearDefaults(Object engine){if(!car(R.get(engine,"vehicleOn")))return;double mode=R.num(R.get(R.call(engine,"getOrCreateVariable","pz_manual_gearbox"),"currentValue"));if(mode==1||mode==2)R.call(R.get(engine,"isAutomaticVar"),"setActive",mode==2,false);}
 public static void toggle(Object gui){Object v=R.get(gui,"vehicle");if(!car(v)||R.yes(R.get(R.get(v,"lockedVar"),"isActive")))return;for(Object e:(Collection<?>)R.get(v,"engines")){Object var=R.call(e,"getOrCreateVariable","pz_manual_gearbox");R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface"),"sendToServer",R.make(p+"packets.instances.PacketEntityVariableSet",var,R.yes(R.get(R.get(e,"isAutomaticVar"),"isActive"))?1.0:2.0));}}
 public static boolean manual(Object engine){return car(R.get(engine,"vehicleOn"))&&!R.yes(R.get(R.get(engine,"isAutomaticVar"),"isActive"));}
 public static boolean simpleThrottle(boolean original,Object v){return original&&(!car(v)||((Collection<?>)R.get(v,"engines")).stream().noneMatch(Mechanics::manual));}
 public static boolean iso(){try{return R.yes(R.call(R.type("dev.zomboid.isotacz.Bridge"),"active"));}catch(IllegalStateException missing){Throwable root=missing;while(root.getCause()!=null)root=root.getCause();if(root instanceof ClassNotFoundException)return false;throw missing;}}
 public static boolean skipNativeClicks(Object player){Object seat=R.call(player,"getEntityRiding");if(seat==null)return iso();if(!R.type(p+"entities.instances.PartSeat").isInstance(seat)||!R.yes(R.get(R.get(seat,"placementDefinition"),"isController")))return false;Object v=R.get(seat,"vehicleOn");return car(v)&&((Collection<?>)R.get(v,"engines")).stream().anyMatch(Mechanics::manual);}

 public static void hudBefore(Object gui){Object v=R.get(gui,"vehicle");if(!car(v))return;instruments(v);Object m=R.get(R.get(v,"definition"),"motorized");R.set(m,"halfHUDOnly",false);R.set(m,"fullHUDOnly",true);R.set(gui,"halfHUDActive",false);R.set(gui,"guiTop",((Number)R.get(gui,"screenHeight")).intValue()-70);}
 public static int width(Object gui,int original){return car(R.get(gui,"vehicle"))?340:original;}
 public static int height(Object gui,int original){return car(R.get(gui,"vehicle"))?66:original;}
 public static Object texture(Object gui,Object original){return car(R.get(gui,"vehicle"))?"mtsofficialpack:textures/guis/zomboid_dashboard.png":original;}
 public static boolean background(Object gui,boolean original){return car(R.get(gui,"vehicle"))?R.yes(R.get(R.get(R.get(gui,"seat"),"placementDefinition"),"isController")):original;}
 static final Map<Object,Object> hints=new WeakHashMap<>();static long noticeUntil;
 static final boolean[] claimed=new boolean[2];
 public static final class RawClick {final int button;boolean canceled;RawClick(int button){this.button=button;}public boolean isAttack(){return button==0;}public boolean isUseItem(){return button==1;}public String getHand(){return "MAIN_HAND";}public void setCanceled(boolean value){canceled=value;}public void setSwingHand(boolean value){}}
 public static void lights(long window,int key,int action,Object callback){if((key!=86&&key!=72)||action!=1)return;Object mc=R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");if(R.get(mc,"screen")!=null||window!=R.lng(R.call(R.call(mc,"getWindow"),"getWindow")))return;Object player=R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"clientInterface"),"getClientPlayer");if(player==null)return;Object seat=R.call(player,"getEntityRiding");if(seat==null||!R.type(p+"entities.instances.PartSeat").isInstance(seat)||!R.yes(R.get(R.get(seat,"placementDefinition"),"isController")))return;Object v=R.get(seat,"vehicleOn");if(!car(v)){if(key==72&&RoadDriving.transport(v)){R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface"),"sendToServer",R.make(p+"packets.instances.PacketEntityVariableSet",R.call(v,"getOrCreateVariable","pz_inspect_request"),1d));R.call(callback,"cancel");}return;}if(key==72){R.make("dev.zomboid/mts/ControlsGUI".replace('/','.'),v);R.call(callback,"cancel");return;}double desired=R.yes(R.get(R.get(v,"headLightVar"),"isActive"))?0:1;for(String field:List.of("headLightVar","runningLightVar"))R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface"),"sendToServer",R.make(p+"packets.instances.PacketEntityVariableSet",R.get(v,field),desired));R.call(callback,"cancel");}
 public static double steering(double original,Object v){return car(v)?Math.max(original,Math.min(4,original*1.5)):original;}
 public static double centering(double original,Object v){return car(v)?Math.max(original,Math.min(6,original*1.25)):original;}
 public static void raw(long window,int button,int action,Object callback){if(button<0||button>1)return;Object mc=R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");if(window!=R.lng(R.call(R.call(mc,"getWindow"),"getWindow")))return;if(action==0&&claimed[button]){claimed[button]=false;R.call(callback,"cancel");return;}if(action!=1||R.get(mc,"screen")!=null)return;if(button==1&&VehicleInteraction.click()){claimed[button]=true;R.call(callback,"cancel");return;}RawClick e=new RawClick(button);click(e);if(e.canceled){claimed[button]=true;R.call(callback,"cancel");}}
 public static void click(Object event){if(!R.yes(R.call(event,"isAttack"))&&!R.yes(R.call(event,"isUseItem")))return;Object player=R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"clientInterface"),"getClientPlayer");if(player==null)return;Object seat=R.call(player,"getEntityRiding");if(seat==null||!R.type(p+"entities.instances.PartSeat").isInstance(seat)||!R.yes(R.get(R.get(seat,"placementDefinition"),"isController")))return;Object v=R.get(seat,"vehicleOn");if(!car(v))return;List<?> manual=((Collection<?>)R.get(v,"engines")).stream().filter(e->!R.yes(R.get(R.get(e,"isAutomaticVar"),"isActive"))).toList();if(manual.isEmpty())return;if(R.yes(R.call(event,"isUseItem"))&&"OFF_HAND".equals(String.valueOf(R.call(event,"getHand")))){R.call(event,"setCanceled",true);R.call(event,"setSwingHand",false);return;}if(!R.yes(R.call(R.call(player,"getHeldStack"),"isEmpty"))){noticeUntil=System.currentTimeMillis()+4000;return;}R.call(event,"setCanceled",true);R.call(event,"setSwingHand",false);for(Object e:manual)R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface"),"sendToServer",R.make(p+"packets.instances.PacketEntityVariableSet",R.get(e,R.yes(R.call(event,"isAttack"))?"shiftUpVar":"shiftDownVar"),1.0));}
 public static void hudSetup(Object gui){if(!car(R.get(gui,"vehicle")))return;Object old=R.get(gui,"healthLabel");R.set(old,"visible",false);Object l=label(gui,((Number)R.get(gui,"guiLeft")).intValue()+12,((Number)R.get(gui,"guiTop")).intValue()+10,"",1f,R.get(R.type(p+"baseclasses.ColorRGB"),"WHITE"));R.set(gui,"healthLabel",l);Object bg=R.get(gui,"background");if(bg!=null)R.set(bg,"ignoreGUILightingState",true);VehicleControls.dashboard(gui);hints.put(gui,label(gui,((Number)R.get(gui,"guiLeft")).intValue()+12,((Number)R.get(gui,"guiTop")).intValue()+48,"",.85f,R.get(R.type(p+"baseclasses.ColorRGB"),"WHITE")));}
 public static void hudState(Object gui){VehicleControls.dashboardState(gui);Object v=R.get(gui,"vehicle");if(!car(v))return;boolean driver=R.yes(R.get(R.get(R.get(gui,"seat"),"placementDefinition"),"isController"));for(Object i:(List<?>)R.get(gui,"instruments")){R.set(i,"visible",false);R.set(i,"ignoreGUILightingState",true);}Object l=R.get(gui,"healthLabel");R.set(l,"visible",driver);Collection<?> engines=(Collection<?>)R.get(v,"engines");double condition=engines.stream().mapToDouble(Mechanics::health).min().orElse(0);R.set(l,"text",String.format("%s %s | Motor %.0f%% | Bat %.0f%% | Vida %.0f%%",engines.isEmpty()?"MANUAL":R.yes(R.get(R.get(engines.iterator().next(),"isAutomaticVar"),"isActive"))?"AUTO":"MANUAL",engines.isEmpty()?"N":gear(engines.iterator().next()),condition*100,battery(v)*100,health(v)*100));Object hint=hints.get(gui);if(hint!=null){R.set(hint,"visible",driver);boolean automatic=!engines.isEmpty()&&R.yes(R.get(R.get(engines.iterator().next(),"isAutomaticVar"),"isActive"));R.set(hint,"text",automatic?"ESPACIO derrape | V luces | H controles":System.currentTimeMillis()<noticeUntil?"Selecciona una casilla vacia en la barra de objetos.":"Izq + / der - | ESPACIO derrape | V luces | H");}}
}
